using System.Web.Mvc;using FindIt.DAL;namespace FindIt.Controllers{public class ClaimController:Controller{ClaimRepository repo=new ClaimRepository();int U=>Session["UserId"]==null?0:(int)Session["UserId"];[HttpGet]public ActionResult Create(int itemId){if(U==0||Session["Role"] as string!="Student")return RedirectToAction("Login","Account");ViewBag.ItemId=itemId;return View();}[HttpPost,ValidateAntiForgeryToken]public ActionResult Create(int itemId,string description){if(U==0||Session["Role"] as string!="Student")return RedirectToAction("Login","Account");if(string.IsNullOrWhiteSpace(description)||description.Length>1000){ModelState.AddModelError("","Claim description required (max 1000 chars). ");ViewBag.ItemId=itemId;return View();}if(!repo.Submit(itemId,U,description)){TempData["Error"]="Claim could not be submitted (closed item, own report, or duplicate claim).";}else TempData["Message"]="Claim submitted for review.";return RedirectToAction("Mine");}public ActionResult Mine(){if(U==0||Session["Role"] as string!="Student")return RedirectToAction("Login","Account");return View(repo.Mine(U));}}}